pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker att;

    function setUp() public {
        c = new C();
        att = new Attacker(c);
    }

    function testFuzz_property(uint256 b, uint256 a) public {
        b = bound(b, 1, 1e30);
        a = bound(a, 1, 1e30);
        att.setAmounts(b, a);
        vm.deal(address(att), b + a);
        bool ok;
        try att.trigger() { ok = true; } catch { ok = false; }
        // Rule: the reentrant addToBalance inside withdrawBalance is always blocked,
        // so the withdraw (and hence the whole trigger) MUST revert.
        assertTrue(!ok);
    }
}

contract Attacker {
    C c;
    uint256 b;
    uint256 a;
    bool stealing;

    constructor(C _c) { c = _c; }

    function setAmounts(uint256 _b, uint256 _a) external { b = _b; a = _a; }

    function trigger() external {
        c.addToBalance{value: b}();
        stealing = true;
        c.withdrawBalance();
        stealing = false;
    }

    receive() external payable {
        if (stealing) {
            // re-enter addToBalance while withdrawBalance is mid-flight
            c.addToBalance{value: a}();
        }
    }
}

